import { ref, computed } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../../stores/auth'
import { homeForRole } from '../../router/links'
import logoSrc from '../../assets/logo.png'

const router = useRouter()
const authStore = useAuthStore()

// Limpia cualquier sesión/token viejo guardado en el navegador
// para evitar que un token caducado bloquee el inicio de sesión.
localStorage.removeItem('token')
localStorage.removeItem('user')

const usuario = ref('')
const contrasena = ref('')
const loading = ref(false)
const success = ref(false)
const errorMsg = ref('')
const shakeKey = ref(0)
const showPassword = ref(false)

const expresionOllita = computed(() => {
  if (success.value) return 'celebrando'
  if (loading.value) return 'pensando'
  if (errorMsg.value) return 'preocupada'
  return 'feliz'
})
const tituloOllita = computed(() => ({
  celebrando: 'Ollita celebra tu ingreso',
  pensando: 'Ollita está verificando tus datos',
  preocupada: 'Ollita no pudo iniciar tu sesión',
  feliz: 'Ollita te da la bienvenida'
})[expresionOllita.value])

const handleLogin = async () => {
  loading.value = true
  errorMsg.value = ''
  try {
    await authStore.login({
      usuario: usuario.value,
      clave: contrasena.value
    })
    success.value = true
    const destino = homeForRole(authStore.user?.rol)
    setTimeout(() => router.push(destino), 650)
  } catch (error) {
    errorMsg.value = error?.response?.data?.error || 'Credenciales inválidas'
    shakeKey.value++
  } finally {
    loading.value = false
  }
}

import { ref, computed, onMounted } from 'vue'
import { useAuthStore } from '../../stores/auth'
import { links } from '../../router/links'
import LineChartFinanciero from '../../components/charts/LineChartFinanciero.vue'
import { formatFecha, soloFecha, saludoSegunHora } from '../../utils/format'
import api from '../../config/axios'

const authStore = useAuthStore()
const loading = ref(true)
const estadoAct = ref('')
let timeoutId = null
const stats = ref({ ventas_mes: 0, egresos_mes: 0, neto_mes: 0 })
const resumenInv = ref({ valor_total: 0, inversiones_mes: 0, articulos_registrados: 0, inversiones_mes_cantidad: 0, ultima_inversion: null })
const alertas = ref({
  stock_bajo: 0,
  agotados: 0,
  adelantos_pendientes: 0,
  solicitudes_pendientes: 0,
  pagos_pendientes: 0,
  empleados_activos: 0,
  pagos_mes: 0,
  caja_pendiente_cierre: false
})
const actividad = ref([])
const rendimientoPuntos = ref([])

const periodos = [
  { key: 'semana', label: 'Semana' },
  { key: 'mes', label: 'Mes' }
]
const periodo = ref('semana')

const ultimaInv = computed(() => resumenInv.value.ultima_inversion || null)
