const disponibles = computed(() =>
  Math.max(0, Number(resumenInv.value.articulos_registrados || 0) - Number(alertas.value.stock_bajo || 0) - Number(alertas.value.agotados || 0))
)

const cambiarPeriodo = (key) => {
