    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
  }).format(new Date())
})

const formatMoney = (val) => Number(val || 0).toLocaleString('es-PE', { minimumFractionDigits: 2 })

const notificaciones = computed(() => {
  const a = alertas.value
