  cierre_caja: 'fa-solid fa-cash-register',
  adelanto: 'fa-solid fa-piggy-bank',
  solicitud_insumo: 'fa-solid fa-box-open',
  inversion: 'fa-solid fa-chart-line'
}

const tipoLabel = (tipo) => ({
