  } catch (e) {
    if (consulta !== consultaActual) return
    salarios.value = []
    toast.add({ severity: 'error', summary: 'Error al calcular salarios', life: 3500 })
  } finally {
    if (consulta === consultaActual) loading.value = false
  }
}

